insert into feh.skills (wiki_name,name,group_name,tag_id,scategory,use_range,refine_path,description,required,next,exclusive,sp,can_use_move,can_use_weapon,might,stat_modifiers,cooldown,weapon_effectiveness,properties) values
  ('Arcane Caladbolg','Arcane Caladbolg','Arcane Caladbolg','SID_魔器・神竜王の剣','weapon',1,null,'Accelerates Special trigger (cooldown count-1).<br><br>At start of player phase or enemy phase, grants Atk/Spd+6,【Draconic Hex】, and【Hexblade】to unit and allies within 2 spaces of unit for 1 turn.<br><br>Grants Atk/Spd/Def/Res+15 to unit, unit deals +25 damage (excluding area-of-effect Specials), reduces damage from foe''s attacks by 15 (excluding area-of-effect Specials), reduces damage from foe''s Specials by an additional 15 (excluding area-of-effect Specials), and reduces the percentage of foe''s non-Special "reduce damage by X%" skills by 50% during combat (excluding area-of-effect Specials).<br><br>【Draconic Hex】<br>Inflicts Atk/Spd/Def/Res-5 on foe during combat and inflicts penalty on each of those stats = 5 - current penalty on each of those stats during combat for 1 turn (min 0; calculates each stat penalty independently).<br><br>【Hexblade】<br>Calculates damage using the lower of foe''s Def or Res during combat for 1 turn (including damage dealt by Specials before combat).','Silver Sword',null,false,300,'Infantry,  Armored,  Cavalry,  Flying','Red Sword',16,'0,16,0,0,0',-1,null,'arcane,random_owner'),
  ('Covenant Blast','Covenant Blast','Covenant Blast','SID_真絆・神竜破','special',null,null,'When Special triggers, boosts damage by unit''s Spd.<br><br>Unit can counterattack regardless of foe''s range.<br><br>At start of player phase or, if defending in Aether Raids, at the start of turn 1 of enemy phase, if there is no support partner on the map, grants【Bonded】to allies with the highest Atk at start of battle ("at start of battle" excludes increases to Atk granted after ally is deployed, such as Legendary Effects, Mythic Effects, Bonus Heroes, Great Talent, etc.).<br><br>At start of player phase or enemy phase, grants【Divinely Inspiring】and "increases Spd difference necessary for foe to make a follow-up attack by 10 during combat" to unit and allies within 3 spaces of unit for 1 turn.<br><br>For support partner and for allies with the 【Bonded】effect active, reduces damage from foe''s attacks by 40% during combat (excluding area-of-effect Specials; counts as if damage reduction is from a Special; this effect triggers only once per turn if foe initiates combat and the number of spaces from ally''s space to foe''s space ≤ 3; this effect triggers any number of times if ally initiates combat or if foe initiates combat and the number of spaces from ally''s space to foe''s space ≥ 4).<br><br>Reduces damage from foe''s attacks by 40% during combat (excluding area-of-effect Specials), and also, if decreasing the Spd difference necessary to make a follow-up attack by 10 would allow unit to trigger a follow-up attack (excluding guaranteed or prevented follow-ups), triggers 【Potent Follow 100%】.<br><br>【Bonded】<br>Grants a status that can trigger certain skill effects to unit for 1 turn.<br><br>【Divinely Inspiring】<br>Grants bonus to unit''s Atk/Spd/Def/Res = X × 3 (X = number of allies with the Divinely Inspiring effect within 3 spaces of unit, excluding unit; max 2), grants Special cooldown count-X to unit before foe''s first attack, and when unit deals damage to foe during combat, restores X × 4 HP to unit during combat.<br><br>【Potent Follow 100%】<br>Triggers an additional follow-up attack immediately after unit''s standard follow-up attack and deals damage = 100% of unit''s normal attack damage (if unit cannot make a follow-up attack, this effect triggers when the standard follow-up attack would occur; this effect is treated like a follow-up attack, so effects like "reduce damage by X%" still apply, but this effect is not affected by effects that prevent follow-ups or "attacks twice" effects; only highest value applied; does not stack).','Astra',null,true,500,'Infantry,  Armored,  Cavalry,  Flying',null,null,null,5,null,'offensive_special,random_owner'),
  ('Divine Aide Arts','Divine Aide Arts','Divine Aide Arts','SID_神竜王とお供の体術','weapon',1,null,'Accelerates Special trigger (cooldown count-1).<br><br>Unit attacks twice (even if foe initiates combat, unit attacks twice). If foe''s Range = 2, calculates damage using the lower of foe''s Def or Res.<br><br>For unit and allies within 3 rows or 3 columns centered on unit, grants Atk/Spd/Def/Res+X (for unit, X = 15; for allies, X = 5), neutralizes effects that grant "Special cooldown charge +X" to foe or inflict "Special cooldown charge -X" on unit or ally, and increases the Spd difference necessary for foe to make a follow-up attack by 10 during combat.<br><br>Unit deals +25 damage (excluding area-of-effect Specials), reduces damage from foe''s attacks by 15 (including area-of-effect Specials; excluding Røkkr area-of-effect Specials), reduces damage from foe''s Specials by an additional 15 (including area-of-effect Specials; excluding Røkkr area-of-effect Specials), and neutralizes effects that guarantee foe''s follow-up attacks and effects that prevent unit''s follow-up attacks during combat.','Flametongue',null,true,400,'Infantry,  Armored,  Cavalry,  Flying','Red Breath,  Blue Breath,  Green Breath,  Colorless Breath',11,'0,11,0,0,0',-1,null,'random_owner'),
  ('Dragons Briar','Dragon''s Briar','Dragon''s Briar','SID_竜の炎茨','special',null,null,'When Special triggers, boosts damage by unit''s Def.<br><br>Reduces damage from foe''s attacks by 40% (twice per combat, excluding area-of-effect Specials) and unit''s next attack deals damage = 40% of foe''s first-attack damage prior to reductions during combat (resets at end of combat; only highest value applied; does not stack).','Ignis',null,false,500,'Infantry,  Armored,  Cavalry,  Flying','Red Breath,  Blue Breath,  Green Breath,  Colorless Breath',null,null,5,null,'offensive_special,random_owner'),
  ('Emblems Marvel','Emblems'' Marvel','Emblems'' Marvel','SID_真紋章の奇跡','passivea',null,null,'Unit can counterattack regardless of foe''s range.<br><br>At start of player phase or enemy phase, grants 【Divinely Inspiring】,【Bulwark】, and "reduces damage from area-of-effect Specials by 80% (excluding Røkkr area-of-effect Specials)" to unit and allies within 3 spaces of unit for 1 turn.<br><br>If the number of allies within 3 spaces of unit ≥ 3, after start-of-turn effects trigger on enemy phase or after combat initiated by foe, neutralizes any penalties on unit (excludes Penalty effects being applied at the same time).<br><br>Grants Atk/Spd/Def/Res+9 to unit, unit deals +X damage (excluding area-of-effect Specials), and reduces damage dealt to unit by X during combat (including from area-of-effect Specials; excluding Røkkr area-of-effect Specials; if this skill''s effect that only triggers for player''s team once per map has already been triggered at start of combat, X = 20; otherwise, X = 10).<br><br>If the number of allies within 3 spaces of unit ≥ 3 and foe initiates combat, if unit''s HP > 1 and foe would reduce unit''s HP to 0 during combat, unit survives with 1 HP, and after combat, restores 99 HP to unit (effect only triggers for player''s team once per map and does not stack with non-Special effects that allow unit to survive with 1 HP if foe''s attack would reduce unit''s HP to 0; when any other such effect triggers on a unit granted this effect, this effect will trigger too).<br><br>【Divinely Inspiring】<br>Grants bonus to unit''s Atk/Spd/Def/Res = X × 3 (X = number of allies with the Divinely Inspiring effect within 3 spaces of unit, excluding unit; max 2), grants Special cooldown count-X to unit before foe''s first attack, and when unit deals damage to foe during combat, restores X × 4 HP to unit during combat.<br><br>【Bulwark】<br>Foes with Range = 1 cannot move through spaces adjacent to unit (does not affect foes with Pass skills). Foes with Range = 2 cannot move through spaces within 2 spaces of unit (does not affect foes with Pass skills).',null,null,true,300,'Infantry,  Armored,  Cavalry,  Flying',null,null,'0,0,0,0,0',null,null,'random_owner'),
  ('Forged Axe','Forged Axe','Forged Axe','SID_鍛錬の斧','weapon',1,null,'At start of player phase or enemy phase, grants Atk/Def+6 to unit and allies within 3 spaces of unit for 1 turn.<br><br>Grants Atk/Spd/Def/Res+5 to unit, unit deals +X damage (excluding area-of-effect Specials), and reduces damage from foe''s attacks by 50% of X during combat (excluding area-of-effect Specials; X = highest total bonuses among unit and allies within 3 spaces of unit).','Steel Axe','Forged Axe Plus',false,200,'Infantry,  Armored,  Cavalry,  Flying','Green Axe',10,'0,10,0,0,0',null,null,'random_owner'),
  ('Forged Axe Plus','Forged Axe+','Forged Axe+','SID_鍛錬の斧＋','weapon',1,null,'At start of player phase or enemy phase, grants Atk/Def+6 to unit and allies within 3 spaces of unit for 1 turn.<br><br>Grants Atk/Spd/Def/Res+5 to unit, unit deals +X damage (excluding area-of-effect Specials), and reduces damage from foe''s attacks by 50% of X during combat (excluding area-of-effect Specials; X = highest total bonuses among unit and allies within 3 spaces of unit).','Forged Axe',null,false,300,'Infantry,  Armored,  Cavalry,  Flying','Green Axe',14,'0,14,0,0,0',null,null,'random_owner'),
  ('Groa weapon','Gróa','Gróa','SID_グロア','weapon',2,null,'Enables【Canto (Dist.; Max ３, Min １)】.<br>Accelerates Special trigger (cooldown count-1).<br><br>After unit acts (if Canto triggers, after Canto), inflicts【Time''s Grip】on closest foes and inflicts Spd/Res-7,【Sabotage】, and【Exposure】on closest foes and foes within 2 spaces of those foes through their next actions.<br><br>After Canto (including cases where action is ended due to Canto Control), if unit has used an Assist skill on the current turn, grants another action to unit, and re-enables Canto (once per turn; does not trigger when affected by effects of traps in Aether Raids during Canto).<br><br>Grants Atk/Spd/Def/Res+15 to unit, unit deals +25 damage (including area-of-effect Specials), and reduces damage from foe''s attacks by 15 during combat (excluding area-of-effect Specials), and also, if unit initiates combat, unit can make a follow-up attack before foe''s next attack.<br><br>【Canto (Dist.; Max ３, Min １)】<br>After an attack, Assist skill, or structure destruction, unit can move spaces = number of spaces from start position to end position unit moved prior to taking action (max ３; min １; if unit used a movement skill that warped them, unit can move １ space(s).)<br><br>【Time''s Grip】<br>Inflicts Atk/Spd/Def/Res-4 during combat. Neutralizes unit''s skills during allies'' combat through unit''s next action.<br><br>【Sabotage】<br>Inflicts penalty on unit''s Atk/Spd/Def/Res during combat = highest penalty on each stat between unit and allies within 2 spaces of unit. Calculates each stat penalty independently.<br><br>【Exposure】<br>Foe''s attacks deal +10 damage.','Thoron;Shine',null,true,400,'Infantry,  Armored,  Cavalry,  Flying','Blue Tome',14,'0,14,0,0,0',-1,null,'random_owner'),
  ('Maiden of Light','Maiden of Light','Maiden of Light','SID_光の女神の娘','passiveb',null,null,'Unit can move through foes'' spaces.<br><br>If a Rally or movement Assist skill is used by unit, grants【Coax】to target ally for 1 turn.<br><br>If a Rally or movement Assist skill is used by unit or targets unit, grants Atk/Spd+6, 【Empathy】, and【Time''s Gate】to unit, target or targeting ally, and allies within 2 spaces of unit and target or targeting ally after movement for 1 turn, and grants Special cooldown-1 to unit and those allies (once per turn).<br><br>For unit and allies with the【Coax】effect active on the map, deals +X damage during combat (X = highest total Atk+Spd bonuses among unit and allies with the【Coax】 effect active + 10; excluding area-of-effect Specials), and if Savior has not triggered, attacks twice during combat.<br><br>For allies with the【Empathy】effect active but without the【Coax】effect active on the map, deals +10 damage during combat (excluding area-of-effect Specials).<br><br>Inflicts Atk/Spd/Res-5 on foes, reduces damage from foe''s attacks by 15 (excluding area-of-effect Specials), neutralizes effects that guarantee foe''s follow-up attacks and effects that prevent unit''s follow-up attacks, and grants Special cooldown charge +1 to unit per attack during combat (only highest value applied; does not stack).<br><br>【Coax】<br>Grants a status that can trigger certain skill effects to unit.<br><br>【Empathy】<br>Grants bonus to unit''s Atk/Spd/Def/Res = number of types of Bonus effects, excluding stat bonuses, and Penalty effects, excluding stat penalties, active on player team and enemy team during combat (max 7).<br><br>【Time''s Gate】<br>Allies within 4 spaces of unit can move to a space adjacent to unit (that turn only).',null,null,true,400,'Infantry,  Armored,  Cavalry,  Flying',null,null,'0,0,0,0,0',null,null,'random_owner'),
  ('Shackle Axe','Shackle Axe','Shackle Axe','SID_枷の斧','weapon',1,null,'At start of turn, and after unit acts (if Canto triggers, after Canto), inflicts Spd/Def-7, 【Spd Shackle】, and【Def Shackle】on closest foes and foes within 2 spaces of those foes through their next actions.<br><br>Grants Atk/Spd/Def/Res+5 to unit, unit deals +20 damage (excluding area-of-effect Specials), and reduces damage from foe''s attacks by 15 during combat (excluding area-of-effect Specials).<br><br>【Spd Shackle】<br>Inflicts penalty on unit''s Spd during combat = number of Penalty effects active on unit + 4, excluding stat penalties (max 8).<br><br>【Def Shackle】<br>Inflicts penalty on unit''s Def during combat = number of Penalty effects active on unit + 4, excluding stat penalties (max 8).','Steel Axe','Shackle Axe Plus',false,200,'Infantry,  Armored,  Cavalry,  Flying','Green Axe',10,'0,10,0,0,0',null,null,'random_owner'),
  ('Shackle Axe Plus','Shackle Axe+','Shackle Axe+','SID_枷の斧＋','weapon',1,null,'At start of turn, and after unit acts (if Canto triggers, after Canto), inflicts Spd/Def-7, 【Spd Shackle】, and【Def Shackle】on closest foes and foes within 2 spaces of those foes through their next actions.<br><br>Grants Atk/Spd/Def/Res+5 to unit, unit deals +20 damage (excluding area-of-effect Specials), and reduces damage from foe''s attacks by 15 during combat (excluding area-of-effect Specials).<br><br>【Spd Shackle】<br>Inflicts penalty on unit''s Spd during combat = number of Penalty effects active on unit + 4, excluding stat penalties (max 8).<br><br>【Def Shackle】<br>Inflicts penalty on unit''s Def during combat = number of Penalty effects active on unit + 4, excluding stat penalties (max 8).','Shackle Axe',null,false,300,'Infantry,  Armored,  Cavalry,  Flying','Green Axe',14,'0,14,0,0,0',null,null,'random_owner'),
  ('Shadow Shift X','Shadow Shift X','Shadow Shift X','SID_影助・引戻・十紋章','passivec',null,null,'When Canto triggers, enables unit to use 【Reposition】on ally (this effect is not treated as an Assist skill; if similar effects are active, this effect does not trigger).<br><br>For unit and allies within 3 rows or 3 columns centered on unit, grants Atk/Spd/Def/Res+4 during combat and restores 7 HP after combat.<br><br>Unit deals +5 damage (excluding area-of-effect Specials) and reduces damage from foe''s first attack by 5 during combat ("first attack" normally means only the first strike; for effects that grant "unit attacks twice," it means the first and second strikes).<br><br>【Reposition】<br>Range = 1. Target moves to opposite side of unit.','Shadow Shift 3',null,false,300,'Cavalry,  Flying',null,null,'0,0,0,0,0',null,null,null),
  ('Swift Life','Swift Life','Swift Life','SID_攻速無欠・生命','passivea',null,null,'Grants HP+7.<br><br>At start of combat, if unit''s HP ≥ 25% or unit is within 3 spaces of an ally, grants Atk/Spd+9 to unit, unit deals +7 damage (excluding area-of-effect Specials), and reduces damage from foe''s first attack by 7 during combat ("first attack" normally means only the first strike; for effects that grant "unit attacks twice," it means the first and second strikes), and also, if unit''s Spd > foe''s Spd, neutralizes effects that guarantee foe''s follow-up attacks and effects that prevent unit''s follow-up attacks during combat.<br><br>At start of combat, if unit''s HP ≥ 25% and unit is within 3 spaces of an ally, grants an additional Atk/Spd+3 to unit during combat.<br><br>At start of combat, if unit''s HP ≥ 25% or unit is within 3 spaces of an ally, restores 7 HP to unit after combat.','AtkSpd Ideal 3',null,false,300,'Infantry',null,null,'7,0,0,0,0',null,null,'random_owner'),
  ('Thunder Specter','Thunder Specter','Thunder Specter','SID_霹靂閃電・鬼没','passivec',null,null,'Enables【Canto (Dist. +1; Max ４)】.<br><br>At start of turn, unit can move 1 extra space (that turn only; does not stack).<br><br>Grants Atk/Spd/Def/Res+X to unit (X = 2 × number of spaces from start position to end position of whoever initiated combat; max 6), unit deals +5 damage (excluding area-of-effect Specials), and reduces damage from foe''s first attack by 5 during combat ("first attack" normally means only the first strike; for effects that grant "unit attacks twice," it means the first and second strikes).<br><br>【Canto (Dist. +1; Max ４)】<br>After an attack, Assist skill, or structure destruction, unit can move spaces = number of spaces from start position to end position of unit before the above, +1. (Max ４.)<br><br>(Unit moves according to movement type. Once per turn. Cannot attack or assist. Only highest value applied. Does not stack. After moving, if a skill that grants another action would be triggered (like with Galeforce), Canto will trigger after the granted action. Unit''s base movement has no effect on movement granted. Cannot warp (using skills like Wings of Mercy) a distance greater than unit would be able to move with normal Canto movement.)','Odd Tempest 3;Even Tempest 3',null,false,300,'Infantry,  Flying','Red Sword,  Blue Lance,  Green Axe,  Red Breath,  Blue Breath,  Green Breath,  Colorless Breath,  Red Beast,  Blue Beast,  Green Beast,  Colorless Beast',null,'0,0,0,0,0',null,null,'random_owner')
