-- Sync learnset : Gróa 1395, Alear (And Sommie!) 1396, Alear (Casual Duelist) 1397,
--                 Jade 1398, Boucheron 1399.
-- Aucune purge : ces 5 héros n'ont aucune ligne, donc pas de doublon.
-- À coller dans Supabase Studio (SQL Editor), APRÈS add_heroes_1395-1399.sql.
begin;

-- 1) Compétences encore absentes de feh.skills (14, vérifiées par wiki_name exact)
on conflict (wiki_name) do update set name=excluded.name, scategory=excluded.scategory,
  use_range=excluded.use_range, refine_path=excluded.refine_path, description=excluded.description,
  required=excluded.required, next=excluded.next, exclusive=excluded.exclusive, sp=excluded.sp,
  can_use_move=excluded.can_use_move, can_use_weapon=excluded.can_use_weapon, might=excluded.might,
  stat_modifiers=excluded.stat_modifiers, cooldown=excluded.cooldown,
  weapon_effectiveness=excluded.weapon_effectiveness, properties=excluded.properties;

-- 2) Learnset lié (hero_id direct)

commit;
